"""Embeds web/index.html (gzip) into src/generated/web_assets.h.

Runs as a PlatformIO pre-build script and can be called standalone:
    python3 tools/embed_web.py
"""
import gzip
import os
import sys


def generate(project_dir):
    src = os.path.join(project_dir, "web", "index.html")
    out_dir = os.path.join(project_dir, "src", "generated")
    out = os.path.join(out_dir, "web_assets.h")
    with open(src, "rb") as f:
        raw = f.read()
    data = gzip.compress(raw, compresslevel=9, mtime=0)
    os.makedirs(out_dir, exist_ok=True)
    lines = [
        "// generated by tools/embed_web.py from web/index.html - do not edit",
        "#pragma once",
        "#include <cstddef>",
        "#include <cstdint>",
        "static const uint8_t kIndexHtmlGz[] = {",
    ]
    for i in range(0, len(data), 20):
        lines.append("  " + ",".join("0x%02x" % b for b in data[i:i + 20]) + ",")
    lines.append("};")
    lines.append("static const size_t kIndexHtmlGzLen = %d;  // %d bytes uncompressed" % (len(data), len(raw)))
    text = "\n".join(lines) + "\n"
    old = None
    if os.path.exists(out):
        with open(out, "r") as f:
            old = f.read()
    if old != text:
        with open(out, "w") as f:
            f.write(text)
    print("embed_web: %d bytes -> %d bytes gzip" % (len(raw), len(data)))


try:
    Import("env")  # noqa: F821  (PlatformIO SCons environment)
    generate(env.subst("$PROJECT_DIR"))  # noqa: F821
except NameError:
    if __name__ == "__main__":
        generate(os.path.dirname(os.path.dirname(os.path.abspath(sys.argv[0]))))
